insert into public.lesson_slides (lesson_id, position, kind, payload)
select l.id, v.pos, v.kind, v.payload::jsonb
from (values
  ('hsk3-01-1', 1, 'fact', '{"emoji":"🏘️","title":"Тётя, которая не родственница","text":"Слово 阿姨 āyí — это и «тётя» (сестра мамы), и вежливое обращение к женщине постарше, и «няня, домработница». Дети зовут так всех взрослых женщин. А 邻居 línjū «сосед» — это «соседний дом»: 邻 «рядом» и 居 «жить». Соседям в Китае придают большое значение: есть поговорка «близкий сосед лучше далёкой родни»."}'),
  ('hsk3-01-1', 2, 'words', '{"title":"Пять слов о людях","items":[{"hanzi":"阿姨","pinyin":"āyí","m":"тётя; вежливо о женщине","emoji":"👩","ex":{"zh":"阿姨，您好！","py":"Āyí, nín hǎo!","m":"Здравствуйте, тётя!"}},{"hanzi":"爱好","pinyin":"àihào","m":"хобби, увлечение","emoji":"🎨","ex":{"zh":"你的爱好是什么？","py":"Nǐ de àihào shì shénme?","m":"Какое у тебя хобби?"}},{"hanzi":"邻居","pinyin":"línjū","m":"сосед","emoji":"🏠","ex":{"zh":"我的邻居很好。","py":"Wǒ de línjū hěn hǎo.","m":"Мой сосед очень хороший."}},{"hanzi":"客人","pinyin":"kèrén","m":"гость","emoji":"🧑‍🤝‍🧑","ex":{"zh":"我家有客人。","py":"Wǒ jiā yǒu kèrén.","m":"У нас дома гости."}},{"hanzi":"聪明","pinyin":"cōngming","m":"умный","emoji":"🧠","ex":{"zh":"她很聪明。","py":"Tā hěn cōngming.","m":"Она очень умная."}}]}'),
  ('hsk3-01-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"👩","options":["客人","阿姨","邻居"],"correct":1},{"emoji":"🎨","options":["爱好","阿姨","聪明"],"correct":0},{"emoji":"🏠","options":["爱好","客人","邻居"],"correct":2},{"emoji":"🧑‍🤝‍🧑","options":["客人","邻居","聪明"],"correct":0},{"emoji":"🧠","options":["爱好","阿姨","聪明"],"correct":2}]}'),
  ('hsk3-01-1', 4, 'theory', '{"title":"Как спросить о человеке","blocks":[{"t":"table","head":["Вопрос","Ответ"],"rows":[["你的爱好是什么？","我的爱好是唱歌。"],["他是你的邻居吗？","是，他是我的邻居。"],["谁是客人？","她是客人。"]]},{"t":"p","text":"爱好 — «хобби» и существительное: 我的爱好是跑步 «мое хобби — бег». 阿姨 в качестве обращения стоит перед глаголом без фамилии: 阿姨，请坐 «тётя, садитесь»."},{"t":"tip","text":"Обращаясь к незнакомой женщине постарше, говорите 阿姨, к мужчине — 叔叔 shūshu."}]}'),
  ('hsk3-01-1', 5, 'quiz', '{"title":"Мини-тест: люди","qs":[{"q":"Как спросить «Какое у тебя хобби?»","options":["你的爱好是什么？","什么你的爱好？","你爱好什么是？"],"correct":0},{"q":"Что значит 邻居?","options":["гость","тётя","сосед"],"correct":2},{"q":"阿姨 можно использовать как вежливое обращение к женщине.","tf":true}]}'),
  ('hsk3-01-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["阿姨","тётя"],["爱好","хобби"],["邻居","сосед"],["客人","гость"],["聪明","умный"]]}'),
  ('hsk3-01-1', 7, 'game', '{"type":"listen","title":"Слушаем: люди","items":[{"say":"阿姨","options":["ǎyí","āyí","āyǐ"],"correct":1},{"say":"爱好","options":["àihǎo","áihào","àihào"],"correct":2},{"say":"邻居","options":["línjù","línjū","lǐnjū"],"correct":1},{"say":"客人","options":["kèrén","kèrěn","kérén"],"correct":0},{"say":"聪明","options":["cóngming","cōngming","cōngmíng"],"correct":1}]}'),
  ('hsk3-01-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","的","爱好","是","唱歌"],"hint":"«Мое хобби — петь.»"},{"answer":["我","的","邻居","很","好"],"hint":"«Мой сосед очень хороший.»"},{"answer":["她","很","聪明"],"hint":"«Она очень умная.»"}]}'),
  ('hsk3-01-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"邻","pinyin":"lín","m":"сосед","hint":"слева 令, справа 阝"},{"hanzi":"居","pinyin":"jū","m":"жить","hint":"сверху 尸, внизу 古"},{"hanzi":"客","pinyin":"kè","m":"гость","hint":"сверху 宀, внизу 各"}]}'),
  ('hsk3-01-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 聪明?","options":["высокий","умный","добрый"],"correct":1},{"q":"Как читается 爱好?","options":["áihào","àihào","àihǎo"],"correct":1},{"q":"Как сказать «У нас дома гости»?","options":["有我家客人。","我家客人有。","我家有客人。"],"correct":2},{"q":"邻居 значит «гость».","tf":false,"explain":"邻居 — сосед, 客人 — гость."},{"q":"Как сказать «Моё хобби — бег»?","options":["我爱好的是跑步。","我的爱好跑步是。","我的爱好是跑步。"],"correct":2}]}'),
  ('hsk3-01-2', 1, 'fact', '{"emoji":"⚖️","title":"Худой, полный, низкий, молодой","text":"Пять прилагательных для описания человека: 矮 ǎi «невысокий», 年轻 niánqīng «молодой», 老 lǎo «пожилой», 胖 pàng «полный», 瘦 shòu «худой». Во всех сочетаниях слева 月 «плоть»: 胖, 脸, 脚. А 瘦 содержит 疒 «болезнь»: так говорили о худобе, похожей на недомогание."}'),
  ('hsk3-01-2', 2, 'words', '{"title":"Пять прилагательных","items":[{"hanzi":"矮","pinyin":"ǎi","m":"низкий (ростом)","emoji":"📏","ex":{"zh":"我弟弟很矮。","py":"Wǒ dìdi hěn ǎi.","m":"Мой младший брат невысокий."}},{"hanzi":"年轻","pinyin":"niánqīng","m":"молодой","emoji":"🧑","ex":{"zh":"她很年轻。","py":"Tā hěn niánqīng.","m":"Она молодая."}},{"hanzi":"老","pinyin":"lǎo","m":"старый, пожилой","emoji":"👴","ex":{"zh":"他不老。","py":"Tā bù lǎo.","m":"Он не старый."}},{"hanzi":"胖","pinyin":"pàng","m":"полный","emoji":"🐷","ex":{"zh":"我的猫很胖。","py":"Wǒ de māo hěn pàng.","m":"Моя кошка очень толстая."}},{"hanzi":"瘦","pinyin":"shòu","m":"худой","emoji":"🦴","ex":{"zh":"他很瘦。","py":"Tā hěn shòu.","m":"Он очень худой."}}]}'),
  ('hsk3-01-2', 3, 'theory', '{"title":"Описание: 很, 不太 и 的","blocks":[{"t":"table","head":["Схема","Пример","Перевод"],"rows":[["很 + прил.","他很瘦。","Он очень худой."],["不太 + прил.","他不太高。","Он не очень высокий."],["прил. + 的 + сущ.","年轻的阿姨","молодая тётя"],["прил. + 的 + сущ.","聪明的孩子","умный ребёнок"]]},{"t":"p","text":"不太 «не очень» мягче, чем 不: 他不太胖 «он не слишком полный». Для определения человека используют «прилагательное + 的 + существительное»: 年轻的阿姨, 聪明的孩子."},{"t":"tip","text":"Не говорите о возрасте человека 他很老 без нужды: вежливее 他年纪大 «ему много лет»."}]}'),
  ('hsk3-01-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["他","不","太","高"],"hint":"«Он не очень высокий.»"},{"answer":["她","是","一个","年轻","的","阿姨"],"hint":"«Она молодая тётя.»"},{"answer":["我","弟弟","很","矮"],"hint":"«Мой младший брат невысокий.»"},{"answer":["我","的","猫","不","太","胖"],"hint":"«Моя кошка не очень толстая.»"}]}'),
  ('hsk3-01-2', 5, 'quiz', '{"title":"Мини-тест: описание","qs":[{"q":"Как сказать «Он не очень высокий»?","options":["他不高太。","他太不高。","他不太高。"],"correct":2},{"q":"Как сказать «молодая тётя»?","options":["年轻的阿姨","阿姨年轻","年轻阿姨的"],"correct":0},{"q":"不太 значит «не очень».","tf":true}]}'),
  ('hsk3-01-2', 6, 'game', '{"type":"listen","title":"Слушаем: прилагательные","items":[{"say":"矮","options":["ài","ái","ǎi"],"correct":2},{"say":"年轻","options":["niánqǐng","niánqīng","niānqīng"],"correct":1},{"say":"老","options":["lào","lǎo","láo"],"correct":1},{"say":"胖","options":["pǎng","páng","pàng"],"correct":2},{"say":"瘦","options":["shóu","shòu","shǒu"],"correct":1}]}'),
  ('hsk3-01-2', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["矮","невысокий"],["年轻","молодой"],["老","пожилой"],["胖","полный"],["瘦","худой"]]}'),
  ('hsk3-01-2', 8, 'game', '{"type":"bughunt","title":"Китайский детектив: описание","cases":[{"buggyText":"他不太是高。","context":"«Он не очень высокий»","options":["他太不高。","他不高太。","他不太高。"],"correct":2},{"buggyText":"年轻阿姨的","context":"«Молодая тётя»","options":["阿姨的年轻","年轻的阿姨","年轻阿姨的"],"correct":1},{"buggyText":"我的猫很是胖。","context":"«Моя кошка очень толстая»","options":["我猫的很胖。","我的猫是很胖。","我的猫很胖。"],"correct":2}]}'),
  ('hsk3-01-2', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 瘦?","options":["худой","высокий","толстый"],"correct":0},{"q":"Как читается 年轻?","options":["niánqīng","niánqǐng","niānqīng"],"correct":0},{"q":"Как сказать «Моя кошка очень толстая»?","options":["我的猫是很胖。","我的猫很胖。","我猫的胖很。"],"correct":1},{"q":"胖 и 瘦 — противоположности.","tf":true},{"q":"Что значит 矮?","options":["старый","молодой","невысокий"],"correct":2}]}'),
  ('hsk3-01-3', 1, 'fact', '{"emoji":"😊","title":"Части тела с «плотью»","text":"В 脸 «лицо» и 脚 «нога, стопа» слева стоит 月 — упрощённая 肉 «плоть». Знак 耳 «ухо» нарисован как ухо, 鼻 «нос» содержит 自 «сам» (раньше показывали на нос, говоря «я»). Слово 可爱 kě''ài «милый» складывается из 可 «достойный» и 爱 «любить»: то, что достойно любви."}'),
  ('hsk3-01-3', 2, 'words', '{"title":"Лицо и тело","items":[{"hanzi":"脸","pinyin":"liǎn","m":"лицо","emoji":"🙂","ex":{"zh":"她的脸很可爱。","py":"Tā de liǎn hěn kě''ài.","m":"Её лицо очень милое."}},{"hanzi":"耳朵","pinyin":"ěrduo","m":"ухо","emoji":"👂","ex":{"zh":"他的耳朵很大。","py":"Tā de ěrduo hěn dà.","m":"У него большие уши."}},{"hanzi":"鼻子","pinyin":"bízi","m":"нос","emoji":"👃","ex":{"zh":"我的鼻子很小。","py":"Wǒ de bízi hěn xiǎo.","m":"У меня маленький нос."}},{"hanzi":"脚","pinyin":"jiǎo","m":"нога, стопа","emoji":"🦶","ex":{"zh":"我的脚很累。","py":"Wǒ de jiǎo hěn lèi.","m":"Мои ноги устали."}},{"hanzi":"可爱","pinyin":"kě''ài","m":"милый","emoji":"🥰","ex":{"zh":"这只猫很可爱。","py":"Zhè zhī māo hěn kě''ài.","m":"Эта кошка очень милая. (只 — счётное слово)"}}]}'),
  ('hsk3-01-3', 3, 'game', '{"type":"listen","title":"Слушаем: части тела","items":[{"say":"脸","options":["lián","liàn","liǎn"],"correct":2},{"say":"耳朵","options":["ěrduǒ","ěrduo","èrduo"],"correct":1},{"say":"鼻子","options":["bízi","bǐzi","bìzi"],"correct":0},{"say":"脚","options":["jiào","jiǎo","jiáo"],"correct":1},{"say":"可爱","options":["kè''ài","kě''āi","kě''ài"],"correct":2}]}'),
  ('hsk3-01-3', 4, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: повторите «liǎn» (3 тон)"}'),
  ('hsk3-01-3', 5, 'theory', '{"title":"Как описать лицо и тело","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["她的脸很可爱。","Её лицо очень милое."],["他的耳朵很大。","У него большие уши."],["我的鼻子不太大。","У меня не слишком большой нос."],["我的脚很累。","Мои ноги устали."]]},{"t":"p","text":"Для частей тела схема «хозяин + 的 + часть + 很 + прилагательное»: 他的耳朵很大. В разговоре о себе 的 иногда опускают: 我脚很累."},{"t":"tip","text":"Слог 子 в 鼻子 безударный: bízi. Так же произносятся 桌子, 椅子."}]}'),
  ('hsk3-01-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🙂","options":["脸","脚","耳朵"],"correct":0},{"emoji":"👂","options":["鼻子","脚","耳朵"],"correct":2},{"emoji":"👃","options":["脸","耳朵","鼻子"],"correct":2},{"emoji":"🦶","options":["可爱","脚","脸"],"correct":1},{"emoji":"🥰","options":["脚","可爱","鼻子"],"correct":1}]}'),
  ('hsk3-01-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["脸","лицо"],["耳朵","ухо"],["鼻子","нос"],["脚","нога, стопа"],["可爱","милый"]]}'),
  ('hsk3-01-3', 8, 'game', '{"type":"chatsim","title":"WeChat: о внешности","messages":[{"speaker":"Друг","text":"你的猫可爱吗？","pinyin":"Nǐ de māo kě''ài ma?","translation":"Твоя кошка милая?","options":["可爱，我猫的是。","很可爱，它的脸很小。","不可爱，是猫。"],"correct":1},{"speaker":"Друг","text":"你的脚怎么了？","pinyin":"Nǐ de jiǎo zěnme le?","translation":"Что с твоей ногой?","options":["我的脚很累。","我脚的是累。","脚我累。"],"correct":0},{"speaker":"Друг","text":"他的耳朵大吗？","pinyin":"Tā de ěrduo dà ma?","translation":"У него большие уши?","options":["是大，耳朵他。","很大，很可爱。","不是，我大。"],"correct":1}]}'),
  ('hsk3-01-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["她","的","脸","很","可爱"],"hint":"«Её лицо очень милое.»"},{"answer":["他","的","耳朵","很","大"],"hint":"«У него большие уши.»"},{"answer":["我","的","脚","很","累"],"hint":"«Мои ноги устали.»"}]}'),
  ('hsk3-01-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 耳朵?","options":["нос","лицо","ухо"],"correct":2},{"q":"Как читается 鼻子?","options":["bìzi","bǐzi","bízi"],"correct":2},{"q":"Как сказать «У меня маленький нос»?","options":["我鼻子的很小。","我的很小鼻子。","我的鼻子很小。"],"correct":2},{"q":"子 в 鼻子 безударный.","tf":true},{"q":"Что значит 可爱?","options":["милый","высокий","умный"],"correct":0}]}'),
  ('hsk3-01-4', 1, 'fact', '{"emoji":"🏡","title":"Рассказ о соседке","text":"Анна рассказывает Ли Мину о своей соседке. В диалоге встретятся 阿姨, 邻居, 爱好, 聪明, 年轻, 瘦, 脸, 可爱, 客人."}'),
  ('hsk3-01-4', 2, 'text', '{"title":"Моя соседка","lines":[{"zh":"安娜：李明，你认识我的邻居吗？","py":"Ānnà: Lǐ Míng, nǐ rènshi wǒ de línjū ma?","m":"Анна: Ли Мин, ты знаешь мою соседку?"},{"zh":"李明：不认识。她是谁？","py":"Lǐ Míng: Bú rènshi. Tā shì shéi?","m":"Ли Мин: Нет. Кто она?"},{"zh":"安娜：她是王阿姨。她不太老，很年轻。","py":"Ānnà: Tā shì Wáng āyí. Tā bú tài lǎo, hěn niánqīng.","m":"Анна: Это тётя Ван. Она не очень старая, она молодая."},{"zh":"李明：她有什么爱好？","py":"Lǐ Míng: Tā yǒu shénme àihào?","m":"Ли Мин: Какие у неё хобби?"},{"zh":"安娜：她喜欢唱歌，也喜欢跑步，所以很瘦。","py":"Ānnà: Tā xǐhuan chànggē, yě xǐhuan pǎobù, suǒyǐ hěn shòu.","m":"Анна: Любит петь и бегать, поэтому она худая."},{"zh":"李明：她聪明吗？","py":"Lǐ Míng: Tā cōngming ma?","m":"Ли Мин: Она умная?"},{"zh":"安娜：非常聪明！她的脸也很可爱。","py":"Ānnà: Fēicháng cōngming! Tā de liǎn yě hěn kě''ài.","m":"Анна: Очень умная! И лицо у неё милое."},{"zh":"李明：今天她来你家做客吗？","py":"Lǐ Míng: Jīntiān tā lái nǐ jiā zuòkè ma?","m":"Ли Мин: Сегодня она придёт к тебе в гости? (做客 «быть в гостях» — новое слово)"},{"zh":"安娜：对，她是我今天的客人。","py":"Ānnà: Duì, tā shì wǒ jīntiān de kèrén.","m":"Анна: Да, она мой гость сегодня."}],"qs":[{"q":"Кто такая тётя Ван?","options":["соседка Анны","учительница","сестра Ли Мина"],"correct":0},{"q":"Тётя Ван очень старая.","tf":false,"explain":"Она не очень старая: 不太老."},{"q":"Какие у неё хобби?","options":["петь и бегать","рисовать и плавать","играть в футбол"],"correct":0},{"q":"Почему она худая?","options":["мало ест","болеет","часто бегает"],"correct":2},{"q":"Анна считает соседку умной.","tf":true},{"q":"Вставьте слово: 她的脸很___。","options":["累","可爱","胖"],"correct":1},{"q":"Кем будет тётя Ван сегодня?","options":["гостьей Анны","учительницей","соседкой Ли Мина"],"correct":0}]}'),
  ('hsk3-01-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["她是我的邻居","она моя соседка"],["她不太老，很年轻","она не очень старая, она молодая"],["她喜欢唱歌","она любит петь"],["她的脸很可爱","у неё милое лицо"],["她是我的客人","она мой гость"]]}'),
  ('hsk3-01-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你认识我的邻居吗","options":["nǐ rènshi wǒ de kèrén ma","nǐ rènshi wǒ de línjū ma"],"correct":1},{"say":"她不太老很年轻","options":["tā hěn lǎo bù niánqīng","tā bú tài lǎo hěn niánqīng"],"correct":1},{"say":"她有什么爱好","options":["tā yǒu shénme míngzi","tā yǒu shénme àihào"],"correct":1},{"say":"她的脸很可爱","options":["tā de liǎn hěn kě''ài","tā de jiǎo hěn kě''ài"],"correct":0}]}'),
